import template from './sw-order-split-deliveries.html.twig';
import './sw-order-split-deliveries.scss';

const { Component } = Shopware;

/**
 * Read-only card listing every delivery of an order together with its shipping
 * address and the line items routed to it. Needed because the standard order
 * detail view is built around a single shipping address and does not surface
 * multiple deliveries clearly.
 *
 * Expects the order to be loaded with the associations:
 *   deliveries, deliveries.shippingOrderAddress(.country),
 *   deliveries.positions, deliveries.positions.orderLineItem
 */
Component.register('swag-order-split-deliveries', {
    template,

    props: {
        order: {
            type: Object,
            required: true,
        },
    },

    computed: {
        deliveries() {
            return this.order?.deliveries ?? [];
        },

        hasMultipleDeliveries() {
            return this.deliveries.length > 1;
        },

        currencyCode() {
            return this.order?.currency?.isoCode ?? 'EUR';
        },
    },

    methods: {
        addressLine(delivery) {
            const a = delivery.shippingOrderAddress;
            if (!a) {
                return '-';
            }
            const country = a.country ? a.country.translated?.name ?? a.country.name : '';
            return [
                `${a.firstName ?? ''} ${a.lastName ?? ''}`.trim(),
                a.street,
                `${a.zipcode ?? ''} ${a.city ?? ''}`.trim(),
                country,
            ].filter(Boolean).join(', ');
        },

        positionsFor(delivery) {
            return delivery.positions ?? [];
        },

        lineItemLabel(position) {
            return position.orderLineItem?.label ?? position.orderLineItemId ?? '-';
        },

        shippingCost(delivery) {
            return delivery.shippingCosts?.totalPrice ?? 0;
        },
    },
});
